{"command":"mkdir -p src
cat <<'EOF' > src/element.rs
use finl_unicode::categories::{get_category, GeneralCategory};

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Element {
    Literal(char),
    Digit,     // \d
    NonDigit,  // \D
    Space,     // \s
    NonSpace,  // \S
    Word,      // \w
    NonWord,   // \W
    Escape(String),
}

pub fn is_digit(c: char) -> bool {
    get_category(c) == GeneralCategory::DecimalNumber
}

pub fn is_space(c: char) -> bool {
    c.is_whitespace()
}

pub fn is_word(c: char) -> bool {
    let cat = get_category(c);
    matches!(
        cat,
        GeneralCategory::UppercaseLetter
            | GeneralCategory::LowercaseLetter
            | GeneralCategory::TitlecaseLetter
            | GeneralCategory::ModifierLetter
            | GeneralCategory::OtherLetter
            | GeneralCategory::NonspacingMark
            | GeneralCategory::SpacingMark
            | GeneralCategory::EnclosingMark
            | GeneralCategory::DecimalNumber
            | GeneralCategory::ConnectorPunctuation
    )
}

pub fn convert_char(
    c: char,
    digits: bool,
    non_digits: bool,
    spaces: bool,
    non_spaces: bool,
    words: bool,
    non_words: bool,
    escape: bool,
    with_surrogates: bool,
) -> Element {
    let is_d = is_digit(c);
    let is_s = is_space(c);
    let is_w = is_word(c);

    if digits && is_d {
        Element::Digit
    } else if spaces && is_s {
        Element::Space
    } else if words && is_w {
        Element::Word
    } else if non_digits && !is_d {
        Element::NonDigit
    } else if non_words && !is_w {
        Element::NonWord
    } else if non_spaces && !is_s {
        Element::NonSpace
    } else if escape && !c.is_ascii() {
        let cp = c as u32;
        if with_surrogates && cp > 0xFFFF {
            let high = 0xD800 + ((cp - 0x10000) >> 10);
            let low = 0xDC00 + ((cp - 0x10000) & 0x3FF);
            Element::Escape(format!("\\u{{{:x}}}\\u{{{:x}}}", high, low))
        } else {
            Element::Escape(format!("\\u{{{:x}}}", cp))
        }
    } else {
        Element::Literal(c)
    }
}
EOF
"}

