    let min = c.get_minor_category();
    maj == MajorCategory::L
        || maj == MajorCategory::M
        || min == MinorCategory::Nd
        || min == MinorCategory::Pc
}

pub fn convert_char(
    c: char,
    digits: bool,
    non_digits: bool,
    spaces: bool,
    non_spaces: bool,
    words: bool,
    non_words: bool,
    escape: bool,
    with_surrogates: bool,
) -> Element {
    let is_d = is_digit(c);
    let is_s = is_space(c);
    let is_w = is_word(c);

    if digits && is_d {
        Element::Digit
    } else if spaces && is_s {
        Element::Space
    } else if words && is_w {
        Element::Word
    } else if non_digits && !is_d {
        Element::NonDigit
    } else if non_words && !is_w {
        Element::NonWord
    } else if non_spaces && !is_s {
        Element::NonSpace
    } else if escape && !c.is_ascii() {
        let cp = c as u32;
        if with_surrogates && cp > 0xFFFF {
            let high = 0xD800 + ((cp - 0x10000) >> 10);
            let low = 0xDC00 + ((cp - 0x10000) & 0x3FF);
            Element::Escape(format!("\\u{{{:x}}}\\u{{{:x}}}", high, low))
        } else {
            Element::Escape(format!("\\u{{{:x}}}", cp))
        }
    } else {
        Element::Literal(c)
    }
}
