    res
}

pub fn render_ast(
    expr: &Expression,
    capture_groups: bool,
    verbose: bool,
    colorize: bool,
    indent_level: usize,
) -> String {
    match expr {
        Expression::Element(e) => match e {
            Element::Literal(c) => escape_char_outside_class(*c),
            Element::Digit => {
                if colorize { "\x1b[103;30m\\d\x1b[0m".to_string() } else { "\\d".to_string() }
            }
            Element::NonDigit => {
                if colorize { "\x1b[103;30m\\D\x1b[0m".to_string() } else { "\\D".to_string() }
            }
            Element::Space => {
                if colorize { "\x1b[103;30m\\s\x1b[0m".to_string() } else { "\\s".to_string() }
            }
            Element::NonSpace => {
                if colorize { "\x1b[103;30m\\S\x1b[0m".to_string() } else { "\\S".to_string() }
            }
            Element::Word => {
                if colorize { "\x1b[103;30m\\w\x1b[0m".to_string() } else { "\\w".to_string() }
            }
            Element::NonWord => {
                if colorize { "\x1b[103;30m\\W\x1b[0m".to_string() } else { "\\W".to_string() }
            }
            Element::Escape(s) => s.clone(),
        },
