            Expression::Optional(Box::new(single))
        } else {
            single
        }
    } else {
        let alt = simplify_alternation(non_empty_prefixes);
        if has_empty {
            Expression::Optional(Box::new(alt))
        } else {
            alt
        }
    };

    let suffix = last.clone();
    if is_empty_expr(&pref_expr) {
        Some(suffix)
    } else {
        Some(Expression::Concatenation(vec![pref_expr, suffix]))
    }
}

fn factor_common_prefix(branches: &[Expression]) -> Option<Expression> {
    if branches.len() < 2 {
        return None;
    }

    let lists: Vec<Vec<Expression>> = branches
        .iter()
        .map(|b| match b {
            Expression::Concatenation(l) => l.clone(),
            other => vec![other.clone()],
        })
        .collect();

    let first = lists[0].first()?;
    for l in &lists[1..] {
        if l.first()? != first {
            return None;
        }
    }

    let mut suffix_branches = Vec::new();
    for mut l in lists {
        l.remove(0);
        if l.is_empty() {
            suffix_branches.push(Expression::Concatenation(vec![]));
        } else if l.len() == 1 {
            suffix_branches.push(l.remove(0));
        } else {
            suffix_branches.push(Expression::Concatenation(l));
        }
    }

    let mut has_empty = false;
    let mut non_empty_suffixes = Vec::new();
    for s in suffix_branches {
        if is_empty_expr(&s) {
            has_empty = true;
        } else {
            non_empty_suffixes.push(s);
        }
    }

    let suff_expr = if non_empty_suffixes.is_empty() {
        Expression::Concatenation(vec![])
    } else if non_empty_suffixes.len() == 1 {
        let single = non_empty_suffixes.remove(0);
        if has_empty {
            Expression::Optional(Box::new(single))
        } else {
            single
        }
    } else {
        let alt = simplify_alternation(non_empty_suffixes);
        if has_empty {
            Expression::Optional(Box::new(alt))
        } else {
            alt
        }
    };

    let prefix = first.clone();
    if is_empty_expr(&suff_expr) {
        Some(prefix)
    } else {
        Some(Expression::Concatenation(vec![prefix, suff_expr]))
    }
