        }
        Expression::Optional(inner) => {
            Expression::Optional(Box::new(process_repetitions(*inner, min_rep, min_len)))
        }
        Expression::Repetition { expr, min, max } => Expression::Repetition {
            expr: Box::new(process_repetitions(*expr, min_rep, min_len)),
