        };

        while i < list.len() {
            if i + base_list.len() <= list.len() && &list[i..i + base_list.len()] == base_list {
                count += 1;
                i += base_list.len();
            } else {
                return None;
            }
        }
        if count > 0 {
            return Some(count);
        }
    }

    None
}
