                new_states[part_id].transitions.insert(elem.clone(), next_part);
            }
        }

        Dfa {
            states: new_states,
            start_state: state_to_part[&self.start_state],
        }
    }

    pub fn to_ast(&self) -> Expression {
        let mut in_degree = vec![0; self.states.len()];
        for node in &self.states {
            for &target in node.transitions.values() {
                in_degree[target] += 1;
            }
        }

        let mut order = Vec::new();
        let mut queue = Vec::new();
        for (i, &deg) in in_degree.iter().enumerate() {
            if deg == 0 {
                queue.push(i);
            }
        }

        while let Some(curr) = queue.pop() {
            order.push(curr);
            for &target in self.states[curr].transitions.values() {
                in_degree[target] -= 1;
                if in_degree[target] == 0 {
                    queue.push(target);
                }
            }
        }

        let mut rev_order = order.clone();
        rev_order.reverse();

        let mut exprs: HashMap<usize, Expression> = HashMap::new();

        for &st in &rev_order {
            let node = &self.states[st];
            let mut branches: Vec<Expression> = Vec::new();

            for (elem, &target) in &node.transitions {
                let target_expr = exprs.get(&target).cloned().unwrap_or(Expression::Concatenation(vec![]));
                let head = Expression::Element(elem.clone());

                match target_expr {
                    Expression::Alternation(list) => {
                        for sub in list {
                            if is_empty_expr(&sub) {
                                branches.push(Expression::Concatenation(vec![head.clone()]));
                            } else {
                                match sub {
                                    Expression::Concatenation(mut l) => {
                                        let mut new_l = vec![head.clone()];
                                        new_l.append(&mut l);
                                        branches.push(Expression::Concatenation(new_l));
