use crate::element::Element;

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Expression {
    Element(Element),
    CharacterClass { chars: Vec<char> },
    Concatenation(Vec<Expression>),
    Alternation(Vec<Expression>),
    Optional(Box<Expression>),
    Repetition {
        expr: Box<Expression>,
        min: u32,
        max: Option<u32>,
    },
}

impl Expression {
    pub fn is_single_token(&self) -> bool {
        match self {
            Expression::Element(_) | Expression::CharacterClass { .. } => true,
            Expression::Concatenation(list) => list.len() == 1 && list[0].is_single_token(),
            _ => false,
        }
    }
}

pub fn escape_char_outside_class(c: char) -> String {
    match c {
        '^' | '$' | '.' | '*' | '+' | '?' | '(' | ')' | '[' | ']' | '{' | '}' | '|' | '\\' | '-' => {
            format!("\\{}", c)
        }
        '\n' => "\\n".to_string(),
        '\r' => "\\r".to_string(),
        '\t' => "\\t".to_string(),
        '\x0C' => "\\f".to_string(),
        '\x0B' => "\\v".to_string(),
        _ => c.to_string(),
    }
}

pub fn escape_char_in_class(c: char) -> String {
    match c {
        '-' | ']' | '[' | '\\' | '^' | '$' => format!("\\{}", c),
        '\n' => "\\n".to_string(),
        '\r' => "\\r".to_string(),
        '\t' => "\\t".to_string(),
        '\x0C' => "\\f".to_string(),
        '\x0B' => "\\v".to_string(),
        _ => c.to_string(),
    }
}

pub fn format_class(chars: &[char]) -> String {
    let mut sorted = chars.to_vec();
    sorted.sort_unstable();
    sorted.dedup();

    let mut res = String::new();
    res.push('[');

    let mut i = 0;
    while i < sorted.len() {
        let start = i;
        while i + 1 < sorted.len() && (sorted[i + 1] as u32) == (sorted[i] as u32) + 1 {
            i += 1;
        }
        let len = i - start + 1;
        if len >= 3 {
            res.push_str(&escape_char_in_class(sorted[start]));
            res.push('-');
            res.push_str(&escape_char_in_class(sorted[i]));
        } else {
            for j in start..=i {
                res.push_str(&escape_char_in_class(sorted[j]));
            }
        }
        i += 1;
    }

    res.push(']');
    res
}

pub fn render_ast(
    expr: &Expression,
    capture_groups: bool,
    verbose: bool,
    colorize: bool,
    indent_level: usize,
) -> String {
    match expr {
        Expression::Element(e) => match e {
            Element::Literal(c) => escape_char_outside_class(*c),
            Element::Digit => {
                if colorize { "\x1b[103;30m\\d\x1b[0m".to_string() } else { "\\d".to_string() }
            }
            Element::NonDigit => {
                if colorize { "\x1b[103;30m\\D\x1b[0m".to_string() } else { "\\D".to_string() }
            }
            Element::Space => {
                if colorize { "\x1b[103;30m\\s\x1b[0m".to_string() } else { "\\s".to_string() }
            }
            Element::NonSpace => {
                if colorize { "\x1b[103;30m\\S\x1b[0m".to_string() } else { "\\S".to_string() }
            }
            Element::Word => {
                if colorize { "\x1b[103;30m\\w\x1b[0m".to_string() } else { "\\w".to_string() }
            }
            Element::NonWord => {
                if colorize { "\x1b[103;30m\\W\x1b[0m".to_string() } else { "\\W".to_string() }
            }
            Element::Escape(s) => s.clone(),
        },
        Expression::CharacterClass { chars } => {
            let class_str = format_class(chars);
            if colorize {
                let mut c_res = String::new();
                for ch in class_str.chars() {
                    if ch == '[' || ch == ']' || ch == '-' {
                        c_res.push_str(&format!("\x1b[1;36m{}\x1b[0m", ch));
                    } else {
                        c_res.push(ch);
                    }
                }
                c_res
            } else {
                class_str
            }
        }
        Expression::Concatenation(list) => {
            let mut res = String::new();
            for item in list {
                res.push_str(&render_ast(item, capture_groups, verbose, colorize, indent_level));
            }
            res
        }
        Expression::Alternation(branches) => {
            let open_paren = if capture_groups { "(" } else { "(?:" };
            let close_paren = ")";

            let (colored_open, colored_close, colored_pipe) = if colorize {
                (
                    format!("\x1b[1;32m{}\x1b[0m", open_paren),
                    "\x1b[1;32m)\x1b[0m".to_string(),
                    "\x1b[1;31m|\x1b[0m".to_string(),
                )
            } else {
                (open_paren.to_string(), close_paren.to_string(), "|".to_string())
            };

            if verbose {
                let current_indent = "  ".repeat(indent_level);
                let inner_indent = "  ".repeat(indent_level + 1);
                let mut res = String::new();
                res.push_str(&colored_open);
                res.push('\n');

                for (i, branch) in branches.iter().enumerate() {
                    if i > 0 {
                        res.push_str(&inner_indent);
                        res.push_str(&colored_pipe);
                        res.push('\n');
                    }
                    res.push_str(&inner_indent);
                    res.push_str(&render_ast(branch, capture_groups, verbose, colorize, indent_level + 1));
                    res.push('\n');
                }

                res.push_str(&current_indent);
                res.push_str(&colored_close);
                res
            } else {
                let mut res = String::new();
                res.push_str(&colored_open);
                for (i, branch) in branches.iter().enumerate() {
                    if i > 0 {
                        res.push_str(&colored_pipe);
                    }
                    res.push_str(&render_ast(branch, capture_groups, verbose, colorize, indent_level));
                }
                res.push_str(&colored_close);
                res
            }
        }
        Expression::Optional(inner) => {
            let q_str = if colorize { "\x1b[1;35m?\x1b[0m" } else { "?" };
            if let Expression::Concatenation(list) = &**inner {
                if list.len() == 2 {
                    if let Expression::Optional(c) = &list[0] {
                        let b = &list[1];
                        let cb = Expression::Concatenation(vec![(**c).clone(), b.clone()]);
                        let b_opt = Expression::Optional(Box::new(b.clone()));
                        let alt = Expression::Alternation(vec![cb, b_opt]);
                        return render_ast(&alt, capture_groups, verbose, colorize, indent_level);
                    }
