                res.push_str(&colored_open);
                for (i, branch) in branches.iter().enumerate() {
                    if i > 0 {
                        res.push_str(&colored_pipe);
                    }
                    res.push_str(&render_ast(branch, capture_groups, verbose, colorize, indent_level));
                }
                res.push_str(&colored_close);
                res
            }
        }
        Expression::Optional(inner) => {
            let q_str = if colorize { "\x1b[1;35m?\x1b[0m" } else { "?" };
            if let Expression::Concatenation(list) = &**inner {
                if list.len() == 2 {
