            eprintln!("error: invalid value '{}' for '--min-substring-length <LENGTH>': Value is not a valid unsigned integer\n\nFor more information, try '--help'.", min_length_str);
            process::exit(2);
        }
    };

    let no_start_anchor = matches.get_flag("no-start-anchor");
    let no_end_anchor = matches.get_flag("no-end-anchor");
    let no_anchors = matches.get_flag("no-anchors");

    let verbose = matches.get_flag("verbose");
    let colorize = matches.get_flag("colorize");
    let ignore_case = matches.get_flag("ignore-case");
    let capture_groups = matches.get_flag("capture-groups");

    // Convert test cases into Element sequences
    let mut token_sequences = Vec::new();
    for tc in &test_cases {
        let mut seq = Vec::new();
        for c in tc.chars() {
            seq.push(convert_char(
                c,
                digits,
                non_digits,
                spaces,
                non_spaces,
                words,
                non_words,
                escape,
                with_surrogates,
            ));
        }
        token_sequences.push(seq);
    }

    let dfa = Dfa::from_sequences(&token_sequences);
    let mut ast = dfa.to_ast();

    if repetitions {
        ast = process_repetitions(ast, min_repetitions, min_substring_length);
    }
    ast = factor_ast(ast);

    // Format output
    let mut output = String::new();

    if ignore_case && verbose {
        if colorize {
            output.push_str("\x1b[40;93m(?ix)\x1b[0m\n");
        } else {
            output.push_str("(?ix)\n");
        }
    } else if ignore_case {
        if colorize {
            output.push_str("\x1b[40;93m(?i)\x1b[0m");
        } else {
            output.push_str("(?i)");
        }
    } else if verbose {
        output.push_str("(?x)\n");
    }

    let start_anchor = if !no_start_anchor && !no_anchors {
        if colorize { "\x1b[1;33m^\x1b[0m" } else { "^" }
    } else {
        ""
    };

    let end_anchor = if !no_end_anchor && !no_anchors {
        if colorize { "\x1b[1;33m$\x1b[0m" } else { "$" }
    } else {
        ""
    };

    if verbose {
        if !start_anchor.is_empty() {
            output.push_str(start_anchor);
            output.push('\n');
        }
        let rendered_body = render_ast(&ast, capture_groups, verbose, colorize, 1);
        if !rendered_body.is_empty() {
            output.push_str("  ");
            output.push_str(&rendered_body);
            output.push('\n');
        }
        if !end_anchor.is_empty() {
            output.push_str(end_anchor);
            output.push('\n');
        }
    } else {
        output.push_str(start_anchor);
        output.push_str(&render_ast(&ast, capture_groups, verbose, colorize, 0));
        output.push_str(end_anchor);
    }

    println!("{}", output);
}

fn process_repetitions(expr: Expression, min_rep: u32, min_len: u32) -> Expression {
    match expr {
        Expression::Alternation(branches) => {
            if let Some(rep_expr) = convert_alternation_to_repetition(&branches, min_rep) {
                return rep_expr;
            }

            let processed_branches: Vec<Expression> = branches
                .into_iter()
                .map(|b| process_repetitions(b, min_rep, min_len))
                .collect();

            simplify_alternation(processed_branches)
        }
        Expression::Concatenation(list) => {
            let mut new_list = Vec::new();
            let mut i = 0;
            while i < list.len() {
                let mut converted = false;
                for sub_len in (min_len as usize..=(list.len() - i)).rev() {
                    let sub = &list[i..i + sub_len];
                    let mut count = 1;
                    while i + (count + 1) * sub_len <= list.len() {
                        if &list[i + count * sub_len..i + (count + 1) * sub_len] == sub {
                            count += 1;
                        } else {
                            break;
                        }
                    }

                    if count > min_rep as usize {
                        let inner = if sub_len == 1 {
                            sub[0].clone()
                        } else {
                            Expression::Concatenation(sub.to_vec())
                        };

                        new_list.push(Expression::Repetition {
                            expr: Box::new(inner),
                            min: count as u32,
                            max: Some(count as u32),
                        });
                        i += count * sub_len;
                        converted = true;
                        break;
                    }
                }

                if !converted {
                    new_list.push(process_repetitions(list[i].clone(), min_rep, min_len));
                    i += 1;
                }
            }

            if new_list.len() == 1 {
                new_list.remove(0)
            } else {
                Expression::Concatenation(new_list)
            }
        }
        Expression::Optional(inner) => {
            Expression::Optional(Box::new(process_repetitions(*inner, min_rep, min_len)))
        }
        Expression::Repetition { expr, min, max } => Expression::Repetition {
            expr: Box::new(process_repetitions(*expr, min_rep, min_len)),
            min,
            max,
        },
        other => other,
    }
}

fn convert_alternation_to_repetition(branches: &[Expression], _min_rep: u32) -> Option<Expression> {
    if branches.len() < 2 {
        return None;
    }

    let base_unit = extract_base_unit(&branches[0])?;

    let mut counts = Vec::new();
    for b in branches {
        let cnt = count_base_unit(b, &base_unit)?;
        counts.push(cnt);
    }

    counts.sort_unstable();
    for (idx, &c) in counts.iter().enumerate() {
        if c != (idx + 1) as u32 {
            return None;
        }
    }

    let min_count = counts[0];
    let max_count = *counts.last().unwrap();

    if base_unit.is_single_token() {
        Some(Expression::Repetition {
            expr: Box::new(base_unit),
            min: min_count,
            max: Some(max_count),
        })
    } else {
        let rep = Expression::Repetition {
            expr: Box::new(base_unit.clone()),
            min: 2,
            max: Some(max_count),
        };
        Some(Expression::Alternation(vec![base_unit, rep]))
    }
}

fn extract_base_unit(expr: &Expression) -> Option<Expression> {
    match expr {
        Expression::Concatenation(list) => {
            if list.is_empty() {
                None
            } else if list.len() == 1 {
                Some(list[0].clone())
            } else {
                Some(list[0].clone())
            }
        }
        other => Some(other.clone()),
    }
}

fn count_base_unit(expr: &Expression, base: &Expression) -> Option<u32> {
    if expr == base {
        return Some(1);
    }

    if let Expression::Concatenation(list) = expr {
        let mut count = 0;
        let mut i = 0;
        let base_list = match base {
            Expression::Concatenation(l) => l.as_slice(),
            other => std::slice::from_ref(other),
        };

        while i < list.len() {
            if i + base_list.len() <= list.len() && &list[i..i + base_list.len()] == base_list {
                count += 1;
                i += base_list.len();
            } else {
                return None;
            }
        }
        if count > 0 {
            return Some(count);
        }
    }

    None
}
