use crate::ast::Expression;
use crate::element::{Element, is_word};
use std::collections::{HashMap, HashSet, BTreeSet};

#[derive(Debug, Clone)]
pub struct TrieNode {
    pub is_accepting: bool,
    pub transitions: HashMap<Element, usize>,
}

pub struct Dfa {
    pub states: Vec<TrieNode>,
    pub start_state: usize,
}

impl Dfa {
    pub fn from_sequences(sequences: &[Vec<Element>]) -> Self {
        let mut states = vec![TrieNode {
            is_accepting: false,
            transitions: HashMap::new(),
        }];

        for seq in sequences {
            let mut curr = 0;
            for elem in seq {
                if let Some(&next) = states[curr].transitions.get(elem) {
                    curr = next;
                } else {
                    let next = states.len();
                    states.push(TrieNode {
                        is_accepting: false,
                        transitions: HashMap::new(),
                    });
                    states[curr].transitions.insert(elem.clone(), next);
                    curr = next;
                }
            }
            states[curr].is_accepting = true;
        }

        let dfa = Dfa {
            states,
            start_state: 0,
        };

        dfa.minimize()
    }

    pub fn minimize(&self) -> Self {
        let num_states = self.states.len();
        if num_states <= 1 {
            return Self {
                states: self.states.clone(),
                start_state: self.start_state,
            };
        }

        let mut accepting: BTreeSet<usize> = BTreeSet::new();
        let mut non_accepting: BTreeSet<usize> = BTreeSet::new();

        for (id, node) in self.states.iter().enumerate() {
            if node.is_accepting {
                accepting.insert(id);
            } else {
                non_accepting.insert(id);
            }
        }

        let mut partition: Vec<BTreeSet<usize>> = Vec::new();
        if !accepting.is_empty() {
            partition.push(accepting.clone());
        }
        if !non_accepting.is_empty() {
            partition.push(non_accepting.clone());
        }

        let mut worklist: Vec<BTreeSet<usize>> = partition.clone();

        let mut alphabet: HashSet<Element> = HashSet::new();
        for node in &self.states {
            for k in node.transitions.keys() {
                alphabet.insert(k.clone());
            }
        }

        while let Some(a_set) = worklist.pop() {
            for symbol in &alphabet {
                let mut x_set: BTreeSet<usize> = BTreeSet::new();
                for (id, node) in self.states.iter().enumerate() {
                    if let Some(&next) = node.transitions.get(symbol) {
                        if a_set.contains(&next) {
                            x_set.insert(id);
                        }
                    }
                }

                if x_set.is_empty() {
                    continue;
                }

                let mut new_partition = Vec::new();
                for y_set in &partition {
                    let intersection: BTreeSet<usize> = y_set.intersection(&x_set).cloned().collect();
                    let difference: BTreeSet<usize> = y_set.difference(&x_set).cloned().collect();

                    if !intersection.is_empty() && !difference.is_empty() {
                        new_partition.push(intersection.clone());
                        new_partition.push(difference.clone());

                        if let Some(pos) = worklist.iter().position(|w| w == y_set) {
                            worklist.remove(pos);
                            worklist.push(intersection);
                            worklist.push(difference);
                        } else {
                            if intersection.len() <= difference.len() {
                                worklist.push(intersection);
                            } else {
                                worklist.push(difference);
                            }
                        }
                    } else {
                        new_partition.push(y_set.clone());
                    }
                }
                partition = new_partition;
            }
        }

        let state_to_part: HashMap<usize, usize> = partition
            .iter()
            .enumerate()
            .flat_map(|(part_id, set)| set.iter().map(move |&st| (st, part_id)))
            .collect();

        let mut new_states = vec![
            TrieNode {
                is_accepting: false,
                transitions: HashMap::new(),
            };
            partition.len()
        ];

        for (part_id, set) in partition.iter().enumerate() {
            let rep = *set.iter().next().unwrap();
            new_states[part_id].is_accepting = self.states[rep].is_accepting;
            for (elem, &next) in &self.states[rep].transitions {
                let next_part = state_to_part[&next];
                new_states[part_id].transitions.insert(elem.clone(), next_part);
            }
        }

        Dfa {
            states: new_states,
            start_state: state_to_part[&self.start_state],
        }
    }

    pub fn to_ast(&self) -> Expression {
        let mut in_degree = vec![0; self.states.len()];
        for node in &self.states {
            for &target in node.transitions.values() {
                in_degree[target] += 1;
            }
        }

        let mut order = Vec::new();
        let mut queue = Vec::new();
        for (i, &deg) in in_degree.iter().enumerate() {
            if deg == 0 {
                queue.push(i);
            }
        }

        while let Some(curr) = queue.pop() {
            order.push(curr);
            for &target in self.states[curr].transitions.values() {
                in_degree[target] -= 1;
                if in_degree[target] == 0 {
                    queue.push(target);
                }
            }
        }

        let mut rev_order = order.clone();
        rev_order.reverse();

        let mut exprs: HashMap<usize, Expression> = HashMap::new();

        for &st in &rev_order {
            let node = &self.states[st];
            let mut branches: Vec<Expression> = Vec::new();

            for (elem, &target) in &node.transitions {
                let target_expr = exprs.get(&target).cloned().unwrap_or(Expression::Concatenation(vec![]));
                let head = Expression::Element(elem.clone());

                match target_expr {
                    Expression::Alternation(list) => {
                        for sub in list {
                            if is_empty_expr(&sub) {
                                branches.push(Expression::Concatenation(vec![head.clone()]));
                            } else {
                                match sub {
                                    Expression::Concatenation(mut l) => {
                                        let mut new_l = vec![head.clone()];
                                        new_l.append(&mut l);
                                        branches.push(Expression::Concatenation(new_l));
                                    }
                                    other => branches.push(Expression::Concatenation(vec![head.clone(), other])),
                                }
                            }
                        }
                    }
                    Expression::Concatenation(mut list) => {
                        let mut new_list = vec![head];
                        new_list.append(&mut list);
                        branches.push(Expression::Concatenation(new_list));
                    }
                    other => {
                        if is_empty_expr(&other) {
                            branches.push(Expression::Concatenation(vec![head]));
                        } else {
                            branches.push(Expression::Concatenation(vec![head, other]));
                        }
                    }
                }
            }

            if node.is_accepting {
                branches.push(Expression::Concatenation(vec![]));
            }

            let branch = if branches.is_empty() {
                Expression::Concatenation(vec![])
            } else if branches.len() == 1 {
                branches.remove(0)
            } else {
                simplify_alternation(branches)
            };

            exprs.insert(st, branch);
        }

        let root_expr = exprs.get(&self.start_state).cloned().unwrap_or(Expression::Concatenation(vec![]));
        flatten_ast(root_expr)
    }
}

pub fn has_optional(expr: &Expression) -> bool {
    match expr {
        Expression::Optional(_) => true,
        Expression::Concatenation(list) => list.iter().any(has_optional),
        Expression::Alternation(list) => list.iter().any(has_optional),
        Expression::Repetition { expr, .. } => has_optional(expr),
        _ => false,
    }
}

pub fn factor_ast(expr: Expression) -> Expression {
    match expr {
        Expression::Alternation(branches) => {
            let has_complex = branches.iter().any(|b| matches!(b, Expression::Alternation(_)) || has_optional(b));
            if has_complex {
                return simplify_alternation(branches);
            }

            let factored_branches: Vec<Expression> = branches.into_iter().map(factor_ast).collect();

            if let Some(res) = try_common_prefix(&factored_branches) {
                return factor_ast(res);
            }

            if let Some(res) = try_common_suffix(&factored_branches) {
                return factor_ast(res);
            }

            simplify_alternation(factored_branches)
        }
        Expression::Concatenation(list) => {
            let new_list: Vec<Expression> = list.into_iter().map(factor_ast).collect();
            if new_list.len() == 1 {
                new_list[0].clone()
            } else {
                Expression::Concatenation(new_list)
            }
        }
        Expression::Optional(inner) => Expression::Optional(Box::new(factor_ast(*inner))),
        Expression::Repetition { expr, min, max } => Expression::Repetition {
            expr: Box::new(factor_ast(*expr)),
            min,
            max,
        },
        other => other,
    }
}

pub fn can_match_empty(expr: &Expression) -> bool {
    match expr {
        Expression::Optional(_) => true,
        Expression::Repetition { min: 0, .. } => true,
        Expression::Concatenation(list) => list.is_empty() || list.iter().all(can_match_empty),
        Expression::Alternation(list) => list.is_empty() || list.iter().any(can_match_empty),
        Expression::Element(_) | Expression::CharacterClass { .. } => false,
        Expression::Repetition { .. } => false,
    }
}

fn try_common_prefix(branches: &[Expression]) -> Option<Expression> {
    if branches.iter().any(|b| matches!(b, Expression::Optional(_))) {
        return None;
    }

    let non_empty_indices: Vec<usize> = branches
        .iter()
        .enumerate()
        .filter(|(_, b)| !is_empty_expr(b))
        .map(|(i, _)| i)
        .collect();

    if non_empty_indices.len() < 2 {
        return None;
    }

    let mut curr_lists: Vec<Vec<Expression>> = non_empty_indices
        .iter()
        .map(|&i| match &branches[i] {
            Expression::Concatenation(l) => l.clone(),
            other => vec![(*other).clone()],
        })
        .collect();

    if curr_lists.iter().any(|l| l.iter().any(|x| matches!(x, Expression::Optional(_)))) {
        return None;
    }

    let mut common_prefix = Vec::new();

    loop {
        if curr_lists[0].is_empty() {
            break;
        }
        let first = curr_lists[0][0].clone();
        if matches!(first, Expression::Optional(_)) {
            break;
        }
        let mut all_match = true;
        for l in &curr_lists[1..] {
            if l.first() != Some(&first) {
                all_match = false;
                break;
            }
        }
        if all_match {
            common_prefix.push(first);
            for l in &mut curr_lists {
                l.remove(0);
            }
        } else {
            break;
        }
    }

    if common_prefix.is_empty() {
        return None;
    }

    let has_empty = branches.iter().any(is_empty_expr) || curr_lists.iter().any(|l| l.is_empty());

    let mut suffix_branches = Vec::new();

    for mut l in curr_lists {
        if l.is_empty() {
            suffix_branches.push(Expression::Concatenation(vec![]));
        } else if l.len() == 1 {
            suffix_branches.push(l.remove(0));
        } else {
            suffix_branches.push(Expression::Concatenation(l));
        }
    }

    let non_empty_suffixes: Vec<Expression> = suffix_branches.into_iter().filter(|b| !is_empty_expr(b)).collect();
    let suff = if non_empty_suffixes.is_empty() {
        Expression::Concatenation(vec![])
    } else if non_empty_suffixes.len() == 1 {
        non_empty_suffixes[0].clone()
    } else {
        simplify_alternation(non_empty_suffixes)
    };

    let pref = if common_prefix.len() == 1 {
        common_prefix.remove(0)
    } else {
        Expression::Concatenation(common_prefix)
    };

    let inner = if is_empty_expr(&suff) {
        if has_empty && !can_match_empty(&pref) {
            Expression::Optional(Box::new(pref))
        } else {
            pref
        }
    } else if has_empty {
        if is_empty_expr(&pref) {
            if can_match_empty(&suff) {
                suff
            } else {
                Expression::Optional(Box::new(suff))
            }
        } else {
            if can_match_empty(&suff) {
                Expression::Concatenation(vec![pref, suff])
            } else {
                Expression::Concatenation(vec![pref, Expression::Optional(Box::new(suff))])
            }
        }
    } else {
        if is_empty_expr(&pref) {
            suff
        } else {
            Expression::Concatenation(vec![pref, suff])
        }
    };

    Some(inner)
}

fn try_common_suffix(branches: &[Expression]) -> Option<Expression> {
    if branches.iter().any(|b| matches!(b, Expression::Optional(_))) {
        return None;
    }

    let non_empty_indices: Vec<usize> = branches
        .iter()
        .enumerate()
        .filter(|(_, b)| !is_empty_expr(b))
        .map(|(i, _)| i)
        .collect();

    if non_empty_indices.len() < 2 {
        return None;
    }

    let lengths: Vec<usize> = non_empty_indices.iter().map(|&i| expr_len(&branches[i])).collect();
    let max_len = *lengths.iter().max()?;
    let min_len = *lengths.iter().min()?;

    let has_empty = branches.iter().any(is_empty_expr);

    if has_empty && max_len - min_len >= 2 {
        let mut short_branches = Vec::new();
        let mut long_branches = Vec::new();
        for &i in &non_empty_indices {
            if expr_len(&branches[i]) == max_len {
                long_branches.push(branches[i].clone());
            } else {
                short_branches.push(branches[i].clone());
            }
        }
        short_branches.push(Expression::Concatenation(vec![]));

        let short_factored = try_common_suffix(&short_branches).map(factor_ast);
        if let Some(short_expr) = short_factored {
            let long_expr = simplify_alternation(long_branches);
            return Some(Expression::Alternation(vec![long_expr, short_expr]));
        }
    }

    let mut curr_lists: Vec<Vec<Expression>> = non_empty_indices
        .iter()
        .map(|&i| match &branches[i] {
            Expression::Concatenation(l) => l.clone(),
            other => vec![(*other).clone()],
        })
        .collect();

    if curr_lists.iter().any(|l| l.iter().any(|x| matches!(x, Expression::Optional(_)))) {
        return None;
    }

    let mut common_suffix = Vec::new();

    loop {
        if curr_lists[0].is_empty() {
            break;
        }
        let last = curr_lists[0].last().unwrap().clone();
        if matches!(last, Expression::Optional(_)) {
            break;
        }
        let mut all_match = true;
        for l in &curr_lists[1..] {
            if l.last() != Some(&last) {
                all_match = false;
                break;
            }
        }
        if all_match {
            common_suffix.insert(0, last);
            for l in &mut curr_lists {
                l.pop();
            }
        } else {
            break;
        }
    }

    if common_suffix.is_empty() {
        return None;
    }

    let has_empty_suffix = branches.iter().any(is_empty_expr) || curr_lists.iter().any(|l| l.is_empty());

    let mut prefix_branches = Vec::new();

    for mut l in curr_lists {
        if l.is_empty() {
            prefix_branches.push(Expression::Concatenation(vec![]));
        } else if l.len() == 1 {
            prefix_branches.push(l.remove(0));
        } else {
            prefix_branches.push(Expression::Concatenation(l));
        }
    }

    for (i, b) in branches.iter().enumerate() {
        if matches!(b, Expression::Optional(_)) && !non_empty_indices.contains(&i) {
            prefix_branches.push(b.clone());
        }
    }

    let non_empty_prefixes: Vec<Expression> = prefix_branches.into_iter().filter(|b| !is_empty_expr(b)).collect();
    let pref = if non_empty_prefixes.is_empty() {
        Expression::Concatenation(vec![])
    } else if non_empty_prefixes.len() == 1 {
        non_empty_prefixes[0].clone()
    } else {
        simplify_alternation(non_empty_prefixes)
    };

    let suff = if common_suffix.len() == 1 {
        common_suffix.remove(0)
    } else {
        Expression::Concatenation(common_suffix)
    };

    let inner = if is_empty_expr(&pref) {
        if has_empty_suffix && !can_match_empty(&suff) {
            Expression::Optional(Box::new(suff))
        } else {
            suff
        }
    } else if has_empty_suffix {
        if is_empty_expr(&suff) {
            if can_match_empty(&pref) {
                pref
            } else {
                Expression::Optional(Box::new(pref))
            }
        } else {
            if can_match_empty(&pref) {
                Expression::Concatenation(vec![pref, suff])
            } else {
                Expression::Concatenation(vec![Expression::Optional(Box::new(pref)), suff])
            }
        }
    } else {
        if is_empty_expr(&pref) {
            suff
        } else {
            Expression::Concatenation(vec![pref, suff])
        }
    };

    let mut final_branches = vec![inner];
    for (i, b) in branches.iter().enumerate() {
        if matches!(b, Expression::Optional(_)) && !non_empty_indices.contains(&i) {
            final_branches.push(b.clone());
        }
    }

    if final_branches.len() == 1 {
        Some(final_branches.remove(0))
    } else {
        Some(simplify_alternation(final_branches))
    }
}

pub fn simplify_alternation(branches: Vec<Expression>) -> Expression {
    let mut flat_branches = Vec::new();
    for b in branches {
        match b {
            Expression::Alternation(inner) => {
                if inner.iter().all(|x| x.is_single_token()) {
                    flat_branches.extend(inner);
                } else {
                    flat_branches.push(Expression::Alternation(inner));
                }
            }
            other => flat_branches.push(other),
        }
    }

    let merged_branches = flat_branches;

    let mut dedupped_branches: Vec<Expression> = Vec::new();
    for b in merged_branches {
        if let Some(prev) = dedupped_branches.last_mut() {
            if let (
                Expression::Repetition { expr: e1, min: min1, max: max1 },
                Expression::Repetition { expr: e2, min: min2, max: max2 },
            ) = (prev.clone(), b.clone()) {
                if e1 == e2 {
                    let new_min = min1.min(min2);
                    let new_max = match (max1, max2) {
                        (Some(m1), Some(m2)) => Some(m1.max(m2)),
                        _ => None,
                    };
                    *prev = Expression::Repetition { expr: e1, min: new_min, max: new_max };
                    continue;
                }
            }
        }
        dedupped_branches.push(b);
    }

    let mut has_shorthand = false;
    let mut literals = Vec::new();
    let mut non_literals = Vec::new();

    for b in &dedupped_branches {
        match b {
            Expression::Concatenation(list) if list.len() == 1 => match &list[0] {
                Expression::Element(Element::Literal(c)) => literals.push(*c),
                Expression::Element(e) if is_shorthand(e) => {
                    has_shorthand = true;
                    non_literals.push(b.clone());
                }
                _ => non_literals.push(b.clone()),
            },
            Expression::Element(Element::Literal(c)) => literals.push(*c),
            Expression::Element(e) if is_shorthand(e) => {
                has_shorthand = true;
                non_literals.push(b.clone());
            }
            _ => non_literals.push(b.clone()),
        }
    }

    if !literals.is_empty() {
        if !has_shorthand && non_literals.is_empty() {
            if literals.len() >= 2 {
                return Expression::CharacterClass { chars: literals };
            }
        } else if has_shorthand {
            let mut non_word_literals = Vec::new();
            let mut remaining_literals = Vec::new();

            for c in literals {
                if !is_word(c) {
                    non_word_literals.push(c);
                } else {
                    remaining_literals.push(c);
                }
            }

            if non_word_literals.len() >= 2 {
                non_literals.push(Expression::CharacterClass { chars: non_word_literals });
            } else {
                for c in non_word_literals {
                    non_literals.push(Expression::Element(Element::Literal(c)));
                }
            }

            for c in remaining_literals {
                non_literals.push(Expression::Element(Element::Literal(c)));
            }

            sort_branches(&mut non_literals);
            return Expression::Alternation(non_literals);
        } else if !non_literals.is_empty() {
            if literals.len() >= 2 {
                non_literals.push(Expression::CharacterClass { chars: literals });
            } else {
                for c in literals {
                    non_literals.push(Expression::Element(Element::Literal(c)));
                }
            }

            sort_branches(&mut non_literals);
            return Expression::Alternation(non_literals);
        }
    }

    let mut result_branches = dedupped_branches;
    sort_branches(&mut result_branches);
    if result_branches.len() == 1 {
        result_branches.remove(0)
    } else {
        Expression::Alternation(result_branches)
    }
}

fn is_shorthand(e: &Element) -> bool {
    matches!(
        e,
        Element::Digit
            | Element::NonDigit
            | Element::Space
            | Element::NonSpace
            | Element::Word
            | Element::NonWord
    )
}

fn sort_branches(branches: &mut Vec<Expression>) {
    if is_repetition_alternation(branches) {
        branches.sort_by_key(get_repetition_count);
    } else {
        branches.sort_by(|a, b| {
            let len_a = expr_len(a);
            let len_b = expr_len(b);
            len_b.cmp(&len_a).then_with(|| sort_key(a).cmp(&sort_key(b)))
        });
    }
}

fn is_repetition_alternation(branches: &[Expression]) -> bool {
    if branches.len() < 2 {
        return false;
    }
    let counts: Vec<u32> = branches.iter().map(get_repetition_count).collect();
    if counts.contains(&0) {
        return false;
    }
    let mut sorted = counts.clone();
    sorted.sort_unstable();
    for (i, &c) in sorted.iter().enumerate() {
        if c != (i + 1) as u32 {
            return false;
        }
    }
    true
}

fn get_repetition_count(expr: &Expression) -> u32 {
    match expr {
        Expression::Repetition { min, .. } => *min,
        Expression::Element(_) | Expression::CharacterClass { .. } => 1,
        Expression::Concatenation(list) => {
            if list.len() == 1 {
                get_repetition_count(&list[0])
            } else {
                1
            }
        }
        _ => 1,
    }
}

fn expr_len(expr: &Expression) -> usize {
    match expr {
        Expression::Element(_) | Expression::CharacterClass { .. } => 1,
        Expression::Concatenation(list) => list.iter().map(expr_len).sum(),
        Expression::Alternation(list) => list.iter().map(expr_len).max().unwrap_or(0),
        Expression::Optional(inner) => expr_len(inner),
        Expression::Repetition { expr, min, max: _ } => expr_len(expr) * (*min as usize),
    }
}

fn sort_key(expr: &Expression) -> (u8, u32, String) {
    match expr {
        Expression::Element(e) => match e {
            Element::Space => (1, 0, String::new()),
            Element::NonWord => (2, 0, String::new()),
            Element::NonDigit => (3, 0, String::new()),
            Element::Literal(c) => (4, *c as u32, String::new()),
            Element::Digit => (5, 0, String::new()),
            Element::Word => (6, 0, String::new()),
            Element::NonSpace => (7, 0, String::new()),
            Element::Escape(s) => (4, 0, s.clone()),
        },
        Expression::CharacterClass { chars } => {
            let first = chars.first().copied().unwrap_or('\0');
            (4, first as u32, String::new())
        }
        Expression::Concatenation(list) => {
            if let Some(first) = list.first() {
                sort_key(first)
            } else {
                (0, 0, String::new())
            }
        }
        Expression::Alternation(list) => {
            if let Some(first) = list.first() {
                sort_key(first)
            } else {
                (0, 0, String::new())
            }
        }
        Expression::Optional(inner) => sort_key(inner),
        Expression::Repetition { expr, .. } => sort_key(expr),
    }
}

fn flatten_ast(expr: Expression) -> Expression {
    match expr {
        Expression::Concatenation(list) => {
            let mut flat = Vec::new();
            for item in list {
                let f = flatten_ast(item);
                match f {
                    Expression::Concatenation(sub) => flat.extend(sub),
                    other => {
                        if !is_empty_expr(&other) {
                            flat.push(other);
                        }
                    }
                }
            }
            if flat.len() == 1 {
                flat.remove(0)
            } else {
                Expression::Concatenation(flat)
            }
        }
        Expression::Alternation(list) => {
            let mut flat = Vec::new();
            for item in list {
                let f = flatten_ast(item);
                match f {
                    Expression::Alternation(sub) => {
                        if sub.iter().all(|x| x.is_single_token()) {
                            flat.extend(sub);
                        } else {
                            flat.push(Expression::Alternation(sub));
                        }
                    }
                    other => flat.push(other),
                }
            }
            simplify_alternation(flat)
        }
        Expression::Optional(inner) => Expression::Optional(Box::new(flatten_ast(*inner))),
        Expression::Repetition { expr, min, max } => Expression::Repetition {
            expr: Box::new(flatten_ast(*expr)),
            min,
            max,
        },
        other => other,
    }
}

pub fn is_empty_expr(expr: &Expression) -> bool {
    match expr {
        Expression::Concatenation(list) => list.is_empty(),
        _ => false,
    }
}
