                    new_list.push(process_repetitions(list[i].clone(), min_rep, min_len));
                    i += 1;
                }
            }

            if new_list.len() == 1 {
                new_list.remove(0)
            } else {
                Expression::Concatenation(new_list)
            }
        }
        Expression::Optional(inner) => {
            Expression::Optional(Box::new(process_repetitions(*inner, min_rep, min_len)))
        }
        Expression::Repetition { expr, min, max } => Expression::Repetition {
            expr: Box::new(process_repetitions(*expr, min_rep, min_len)),
            min,
            max,
        },
        other => other,
    }
}

fn convert_alternation_to_repetition(branches: &[Expression], _min_rep: u32) -> Option<Expression> {
    if branches.len() < 2 {
        return None;
    }

    let base_unit = extract_base_unit(&branches[0])?;

    let mut counts = Vec::new();
    for b in branches {
        let cnt = count_base_unit(b, &base_unit)?;
        counts.push(cnt);
    }

    counts.sort_unstable();
    for (idx, &c) in counts.iter().enumerate() {
        if c != (idx + 1) as u32 {
            return None;
        }
    }

    let min_count = counts[0];
    let max_count = *counts.last().unwrap();

    if base_unit.is_single_token() {
        Some(Expression::Repetition {
            expr: Box::new(base_unit),
            min: min_count,
            max: Some(max_count),
        })
    } else {
        let rep = Expression::Repetition {
            expr: Box::new(base_unit.clone()),
            min: 2,
            max: Some(max_count),
        };
        Some(Expression::Alternation(vec![base_unit, rep]))
    }
}

fn extract_base_unit(expr: &Expression) -> Option<Expression> {
    match expr {
        Expression::Concatenation(list) => {
            if list.is_empty() {
                None
            } else if list.len() == 1 {
                Some(list[0].clone())
            } else {
                Some(list[0].clone())
            }
        }
        other => Some(other.clone()),
    }
}

fn count_base_unit(expr: &Expression, base: &Expression) -> Option<u32> {
    if expr == base {
        return Some(1);
    }

    if let Expression::Concatenation(list) = expr {
        let mut count = 0;
        let mut i = 0;
        let base_list = match base {
            Expression::Concatenation(l) => l.as_slice(),
            other => std::slice::from_ref(other),
        };

        while i < list.len() {
            if i + base_list.len() <= list.len() && &list[i..i + base_list.len()] == base_list {
                count += 1;
                i += base_list.len();
            } else {
                return None;
            }
        }
        if count > 0 {
            return Some(count);
        }
    }

    None
}
